using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
namespace VideoGame.Editor {
public static class CorporateEnemyAssets {
 const string Root="Assets/Game/Resources/Detailed/CorporateEnemies/",Output="artifacts/biome-parallel/enemy-production/corporate/";
 [Serializable]class Maps{public string Albedo,Normal,Emission,Occlusion;}
 [Serializable]class Constants{public float[] Albedo,Emission;public float Metallic,Roughness;}
 [Serializable]class Surface{public string name,id;public Maps maps;public Constants constants;public bool glass;public float emissionStrength;}
 [Serializable]class Model{public string id,shotParent;public float[] shotOrigin;public float targetHeight;public Surface[] materials;public int triangles,bones,unweighted;}
 [Serializable]class Manifest{public Model CorporateMelee,CorporateGunner,CorporateAoe,CorporateHeavy;public IEnumerable<Model> Models=>new[]{CorporateMelee,CorporateGunner,CorporateAoe,CorporateHeavy}.Where(m=>m!=null);}
 static string NameKey(string value)=>new string(value.Where(char.IsLetterOrDigit).ToArray());
 public static void Build(){
  Directory.CreateDirectory(Root+"Materials");Directory.CreateDirectory(Root+"Prefabs");AssetDatabase.Refresh();var data=JsonUtility.FromJson<Manifest>(File.ReadAllText(Root+"manifest.json"));
  foreach(string file in Directory.GetFiles(Root+"Textures","*.png",SearchOption.AllDirectories)){string path=file.Replace('\\','/');var i=(TextureImporter)AssetImporter.GetAtPath(path);int maximum=path.Contains("Albedo")||path.Contains("Normal")?2048:1024;bool color=path.Contains("Albedo")||path.Contains("Emission");var type=path.Contains("Normal")?TextureImporterType.NormalMap:TextureImporterType.Default;if(i.maxTextureSize!=maximum||i.sRGBTexture!=color||i.textureType!=type){i.maxTextureSize=maximum;i.sRGBTexture=color;i.textureType=type;i.SaveAndReimport();}}
  foreach(var info in data.Models){string id=info.id;string source=Root+"Models/"+id+".fbx";var importer=(ModelImporter)AssetImporter.GetAtPath(source);if(importer.importAnimation||importer.importCameras||importer.importLights||!importer.isReadable||importer.animationType!=ModelImporterAnimationType.Legacy||importer.materialImportMode!=ModelImporterMaterialImportMode.ImportStandard){importer.importAnimation=importer.importCameras=importer.importLights=false;importer.isReadable=true;importer.animationType=ModelImporterAnimationType.Legacy;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.SaveAndReimport();}var model=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(source));model.name=id;foreach(var c in model.GetComponentsInChildren<Animator>())UnityEngine.Object.DestroyImmediate(c);foreach(var c in model.GetComponentsInChildren<Animation>())UnityEngine.Object.DestroyImmediate(c);
   foreach(var r in model.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(sourceMat=>{var s=info.materials.FirstOrDefault(m=>NameKey(m.name)==NameKey(sourceMat.name))??info.materials.OrderByDescending(m=>m.name.Length).FirstOrDefault(m=>NameKey(sourceMat.name).StartsWith(NameKey(m.name),StringComparison.Ordinal));if(s==null)throw new Exception(id+" lost source material "+sourceMat.name);return SurfaceMaterial(id,s);}).ToArray();if(r is SkinnedMeshRenderer skin)skin.updateWhenOffscreen=true;}
   var b=Bounds(model);if(Mathf.Abs(b.size.y-info.targetHeight)>.035f)throw new Exception(id+" actual weighted height mismatch "+b.size.y+" expected "+info.targetHeight);if(Mathf.Abs(b.min.y)>.025f)throw new Exception(id+" source ground mismatch "+b.min.y);
   var children=model.transform.Cast<Transform>().ToArray();var motion=new GameObject("motion.root").transform;motion.SetParent(model.transform,false);motion.position=b.center;foreach(var c in children)c.SetParent(motion,true);
   var parent=model.GetComponentsInChildren<Transform>().First(t=>t.name==info.shotParent);var socket=new GameObject("ShotOrigin").transform;socket.SetParent(parent,false);socket.position=new Vector3(info.shotOrigin[0],info.shotOrigin[1],info.shotOrigin[2]);socket.rotation=Quaternion.identity;
   CorporateEnemyClips.Bake(model,id,b);PrefabUtility.SaveAsPrefabAsset(model,Root+"Prefabs/"+id+".prefab");UnityEngine.Object.DestroyImmediate(model);
  }AssetDatabase.SaveAssets();Debug.Log("CORPORATE_ENEMIES_BUILT models="+data.Models.Count()+" clips="+data.Models.Count()*ActorAnimationBuilder.Names.Length);
 }
 static Material SurfaceMaterial(string id,Surface s){string path=Root+"Materials/"+id+"_"+s.id+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(m,path);}m.shaderKeywords=new string[0];m.mainTexture=Tex(id,s.maps.Albedo);m.color=s.maps.Albedo!=null?Color.white:s.constants?.Albedo?.Length>=4?new Color(s.constants.Albedo[0],s.constants.Albedo[1],s.constants.Albedo[2],s.constants.Albedo[3]):Color.white;if(!string.IsNullOrEmpty(s.maps.Normal)){m.SetTexture("_BumpMap",Tex(id,s.maps.Normal));m.EnableKeyword("_NORMALMAP");}m.SetTexture("_MetallicGlossMap",Tex(id,s.id+"_MetalSmooth.png"));m.SetFloat("_GlossMapScale",1);m.EnableKeyword("_METALLICGLOSSMAP");m.SetTexture("_OcclusionMap",Tex(id,s.maps.Occlusion));if(!string.IsNullOrEmpty(s.maps.Emission)){m.SetTexture("_EmissionMap",Tex(id,s.maps.Emission));m.SetColor("_EmissionColor",Color.white*Mathf.Max(0,s.emissionStrength));m.EnableKeyword("_EMISSION");}else if(s.constants?.Emission?.Length>=3&&s.constants.Emission.Take(3).Max()>0&&s.emissionStrength>0){m.SetColor("_EmissionColor",new Color(s.constants.Emission[0],s.constants.Emission[1],s.constants.Emission[2])*s.emissionStrength);m.EnableKeyword("_EMISSION");}if(s.glass){var c=m.color;c.a=.35f;m.color=c;m.SetFloat("_Mode",3);m.SetInt("_SrcBlend",1);m.SetInt("_DstBlend",10);m.SetInt("_ZWrite",0);m.EnableKeyword("_ALPHAPREMULTIPLY_ON");m.renderQueue=3000;}m.enableInstancing=true;EditorUtility.SetDirty(m);return m;}
 static Texture2D Tex(string id,string file)=>string.IsNullOrEmpty(file)?null:AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"Textures/"+id+"/"+file);
 public static Bounds Bounds(GameObject o){bool first=true;var bounds=new Bounds();foreach(var skin in o.GetComponentsInChildren<SkinnedMeshRenderer>()){var mesh=new Mesh();skin.BakeMesh(mesh);foreach(var p in mesh.vertices){var world=skin.transform.TransformPoint(p);if(first){bounds=new Bounds(world,Vector3.zero);first=false;}else bounds.Encapsulate(world);}UnityEngine.Object.DestroyImmediate(mesh);}if(first)throw new Exception("No source weighted geometry");return bounds;}
 static Vector3[] Snapshot(GameObject o){var result=new List<Vector3>();foreach(var skin in o.GetComponentsInChildren<SkinnedMeshRenderer>()){var mesh=new Mesh();skin.BakeMesh(mesh);result.AddRange(mesh.vertices.Select(v=>skin.transform.TransformPoint(v)));UnityEngine.Object.DestroyImmediate(mesh);}return result.ToArray();}
 public static void Proof(){Build();var report=new List<string>();var data=JsonUtility.FromJson<Manifest>(File.ReadAllText(Root+"manifest.json"));
  foreach(var info in data.Models){var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var actor=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"Prefabs/"+info.id+".prefab"));var skins=actor.GetComponentsInChildren<SkinnedMeshRenderer>();if(skins.Sum(s=>s.sharedMesh.triangles.Length/3)!=info.triangles)throw new Exception("Triangle mismatch "+info.id);if(skins.Any(s=>s.bones.Length==0))throw new Exception("Missing actual weighted bones");
   foreach(string state in ActorAnimationBuilder.Names){var clip=Resources.Load<AnimationClip>("CorporateEnemyAnimations/"+info.id+"/"+state);if(!clip||!clip.legacy||AnimationUtility.GetCurveBindings(clip).Length==0)throw new Exception("Missing Legacy motion "+info.id+" "+state);clip.SampleAnimation(actor,0);var a=Snapshot(actor);clip.SampleAnimation(actor,clip.length*.37f);var b=Snapshot(actor);float max=a.Zip(b,Vector3.Distance).Max();if(max<.0001f)throw new Exception("No world-space weighted motion "+info.id+" "+state);report.Add(info.id+" "+state+" worldMetreDelta="+max.ToString("F5"));}
   var idle=Resources.Load<AnimationClip>("CorporateEnemyAnimations/"+info.id+"/Idle");idle.SampleAnimation(actor,0);var bound=Bounds(actor);if(Mathf.Abs(bound.min.y)>.03f)throw new Exception("Idle ground mismatch "+bound.min.y);
   var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.GetComponent<Renderer>().sharedMaterial=new Material(Shader.Find("Standard")){color=new Color(.075f,.09f,.11f)};var light=new GameObject("Proof key").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.1f;light.transform.rotation=Quaternion.Euler(45,-30,0);RenderSettings.ambientLight=new Color(.32f,.35f,.39f);
   var camera=new GameObject("Proof camera").AddComponent<Camera>();camera.orthographic=true;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.035f,.05f);camera.transform.rotation=Quaternion.Euler(50,45,0);camera.farClipPlane=100;float size=Mathf.Max(1.5f,info.targetHeight*1.1f);
   foreach(string state in new[]{"Idle","RunForward",info.id=="CorporateMelee"?"Melee":info.id=="CorporateAoe"?"Cast":"Fire","Death"}){var clip=Resources.Load<AnimationClip>("CorporateEnemyAnimations/"+info.id+"/"+state);clip.SampleAnimation(actor,state=="Death"?clip.length:clip.length*.28f);Capture(camera,new Vector3(0,info.targetHeight*.5f,0),size,info.id+"-"+state+".png");}
   idle.SampleAnimation(actor,0);var reference=UnityEngine.Object.Instantiate(Resources.Load<GameObject>(VideoGame.PlayerRig.PrefabPath));foreach(var m in reference.GetComponentsInChildren<MonoBehaviour>())m.enabled=false;reference.transform.position=new Vector3(2,0,0);Capture(camera,new Vector3(.6f,1,0),7.5f,info.id+"-gameplay.png");UnityEngine.Object.DestroyImmediate(reference);report.Add(info.id+" sourceTriangles="+info.triangles+" height="+bound.size.y+" ground="+bound.min.y+" ShotOrigin="+actor.GetComponentsInChildren<Transform>().Single(t=>t.name=="ShotOrigin").position);
  }
  File.WriteAllLines(Output+"unity-production-proof.txt",report);var prefabs=AssetDatabase.FindAssets("t:Prefab",new[]{Root+"Prefabs"}).Select(AssetDatabase.GUIDToAssetPath).ToArray();File.WriteAllLines(Output+"dependencies.txt",AssetDatabase.GetDependencies(prefabs,true).OrderBy(p=>p).Select(p=>AssetDatabase.AssetPathToGUID(p)+" "+p));Debug.Log("CORPORATE_ENEMY_PRODUCTION_PROOF_PASS models="+data.Models.Count()+" allLegacyClips="+data.Models.Count()*ActorAnimationBuilder.Names.Length);
 }
 static void Capture(Camera c,Vector3 p,float size,string name){c.orthographicSize=size;c.transform.position=p-c.transform.forward*18;var rt=new RenderTexture(1200,1000,24){antiAliasing=4};c.targetTexture=rt;c.Render();var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(1200,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1200,1000),0,0);tex.Apply();File.WriteAllBytes(Output+name,tex.EncodeToPNG());RenderTexture.active=old;c.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}
}}
